<script lang="ts">
 import {onMount} from 'svelte';
 import {Button} from '$lib/components/ui/button';
 import * as Select from '$lib/components/ui/select';
 import {LoaderCircle,ArrowUpRight} from '@lucide/svelte';
 import {request} from './api';
 import {historyQuery,mergeHistoryEntries} from './billing-history.mjs';
 interface Entry{id:string;provider:string;product:string;amount_cents:number;currency:string;status:string;created_at:string;paid_at:string|null;management_url:string;receipt_available:boolean}
 let entries=$state<Entry[]>([]),cursor=$state(''),provider=$state('all'),product=$state('all'),loading=$state(false),error=$state('');
 let mounted=false,sequence=0;let controller:AbortController|undefined;
 onMount(()=>{mounted=true;void load();return()=>{mounted=false;sequence++;controller?.abort();};});
 async function load(more=false){
  controller?.abort();controller=new AbortController();const current=++sequence;loading=true;error='';
  const query=historyQuery(provider,product,more?cursor:'');
  try{const result=await request(`/billing/history?${query}`,undefined,undefined,{},false,{signal:controller.signal});if(!mounted||sequence!==current)return;entries=more?mergeHistoryEntries(entries,result.items):result.items;cursor=result.next_cursor||'';}catch(e){if(mounted&&sequence===current&&(e as Error).name!=='AbortError')error=(e as Error).message;}finally{if(mounted&&sequence===current)loading=false;}
 }
 const money=(entry:Entry)=>new Intl.NumberFormat(undefined,{style:'currency',currency:entry.currency.toUpperCase()}).format(entry.amount_cents/100);
 const status=(value:string)=>value.replaceAll('_',' ');
</script>
<section class="billing-history" aria-labelledby="billing-history-title"><div class="section-heading"><h2 id="billing-history-title">Payment history</h2><Button variant="ghost" size="sm" disabled={loading} onclick={()=>load()}>Refresh</Button></div><p class="subtle">Card and crypto purchases, together. Amounts show the quoted product price; crypto transfer totals and fees are on the invoice.</p>
<div class="filters"><div><label for="history-method">Method</label><Select.Root type="single" value={provider} onValueChange={(value)=>{provider=value;void load();}}><Select.Trigger id="history-method" class="w-full">{provider==='stripe'?'Card · Stripe':provider==='cryptorails'?'Crypto · CryptoRails':'All methods'}</Select.Trigger><Select.Content>{#each [{value:'all',label:'All methods'},{value:'stripe',label:'Card · Stripe'},{value:'cryptorails',label:'Crypto · CryptoRails'}] as item}<Select.Item value={item.value} label={item.label}>{item.label}</Select.Item>{/each}</Select.Content></Select.Root></div><div><label for="history-product">Product</label><Select.Root type="single" value={product} onValueChange={(value)=>{product=value;void load();}}><Select.Trigger id="history-product" class="w-full">{product==='credits'?'Generation credits':product==='premium'?'Premium':'All purchases'}</Select.Trigger><Select.Content>{#each [{value:'all',label:'All purchases'},{value:'credits',label:'Generation credits'},{value:'premium',label:'Premium'}] as item}<Select.Item value={item.value} label={item.label}>{item.label}</Select.Item>{/each}</Select.Content></Select.Root></div></div>
{#if error}<div class="cloud-alert" role="alert">{error}<Button size="sm" variant="ghost" onclick={()=>load()}>Try again</Button></div>{/if}
<div aria-busy={loading}>{#each entries as entry(entry.id)}<article class="history-entry"><div><strong>{entry.product==='premium'?'Premium':'Generation credits'}</strong><small>{entry.provider==='stripe'?'Card · Stripe':'Crypto · CryptoRails'} · {new Date(entry.created_at).toLocaleDateString()}</small><span class="status">{status(entry.status)}</span>{#if entry.paid_at}<small>Confirmed {new Date(entry.paid_at).toLocaleDateString()}</small>{/if}</div><div class="entry-action"><strong>{money(entry)}</strong><Button href={entry.management_url} variant="ghost" size="sm">{entry.provider==='cryptorails'?'Invoice':entry.product==='premium'?'Manage':'Credit activity'}<ArrowUpRight size={14}/></Button></div></article>{:else}{#if !loading&&!error}<p class="quiet-empty">No purchases match these filters.</p>{/if}{/each}</div>
{#if loading}<p class="loading" role="status"><LoaderCircle size={16} class="animate-spin"/>Loading purchases…</p>{/if}{#if cursor}<Button class="mt-4" variant="outline" disabled={loading} onclick={()=>load(true)}>Load older purchases</Button>{/if}<p class="field-help">Pending records are not payment confirmation. Return to an existing invoice or subscription to resolve an unfinished payment.</p>
</section>
<style>.billing-history{min-width:0}.filters{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:18px 0}.filters label{display:block;margin-bottom:7px;font-size:12px}.history-entry{display:flex;justify-content:space-between;gap:16px;padding:17px 0;border-bottom:1px solid var(--border)}.history-entry strong{display:block;font-size:13px;font-weight:600}.history-entry small{display:block;font-size:11px;color:var(--muted-foreground);margin:6px 0}.entry-action{text-align:right}.entry-action :global(a){margin-top:8px}.loading{display:flex;align-items:center;gap:8px;font-size:13px;padding:16px 0}.status{display:inline-block;margin-top:4px;text-transform:capitalize}@media(max-width:450px){.filters{grid-template-columns:1fr}.history-entry{gap:8px}}</style>
